INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (1, 137, 'Customers visiting photos', '../upload/image/20180923/20180923105116_72388.jpg', '<p></p><p><strong><span style="color:#E53333;font-size:32px;">Customers visiting photos</span></strong></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921130956_55502.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921130956_14045.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921130957_20555.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921130957_44142.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921130957_10442.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921130957_86094.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921130957_83267.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921131024_10991.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921131024_90186.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921131024_10227.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921131024_48056.jpg"/></p> <p><br/></p> <p><img alt="" src="../upload/image/20180921/20180921131024_43211.jpeg"/></p> <p><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:24px;"><strong>Please point this PDF to visit more photos,</strong></span></p> <p><a class="ke-insertfile" href="../upload/file/20180921121225_11700.pdf" target="_blank"><span style="color:#337FE5;font-family:Verdana;font-size:16px;"><strong>Asia Pacific -Customers visiting photos.pdf</strong></span></a></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (1, 101, 'Culture', '../upload/image/20180824/20180824195345_47512.jpg', '<p></p><p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style=''font-family:Calibri, "font-size:24px;''><strong><span style="color:blue;line-height:18px;"><img alt="" src="../upload/image/20180824/20180824195151_52261.jpg"/><img alt="" src="../upload/image/20180824/20180824195151_31478.jpg"/></span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;line-height:18px;font-family:Tahoma;font-size:18px;">Q1: Are you A Manufacturer or A Trading Company?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A: we are not only More than ten years professional manufacturer. Mainly deal with oversea market’s exporting business!</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style=''line-height:24px;font-family:Calibri, "font-size:24px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">But also have a</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;background-color:white;">specialty</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">sales team of ages experienced international trade business. We can do transportation easily By sea, By air, By trains and by Air-express. Easily transact several transportation methods, such as mixed loading container, less than container loading, full container loading.</span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style=''line-height:24px;font-family:Calibri, "font-size:24px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Plus, Asia pacific industry group</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Is an integrated companies approved by China National Ministry of Foreign Trade and General Administration of Customs. The company, as a full-invested subsidiary company of Asia Pacific Industry Group Co., Limited, has its own independent import and export rights. Registered in Hefei City, Anhui Province, P.R. China.</span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style=''line-height:24px;font-family:Calibri, "font-size:24px;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Here you’ll find up:</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;background-color:white;">Highly active</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">, very convenient, professional</span><span style="color:#333333;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;background-color:white;">specialty</span></span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">, vitality and vigor, zero-distance service!</span></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q2: Can you OEM and ODM?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A: We have high-advanced production equipment to ensure the quality of buyer’s order. Meanwhile there is a dedicated design team to help with the sample artwork for free. On the other hand your design will be 100% safe under NDA.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q3: Can we get some samples from factory?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A: Yes, you can get available sample in our stock. Free for samples, but shipping fees is for buyer’s account. And after firm order, we will return the shipping fees to buyers or deduct the shipping fees from buyer’s firm order payment.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q4: Can you accept the major currencies all over the world?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">Yes, We can. And we can accept the payment currency, such as: USD, EUR,HKD,GBP,JPY,AUD,RMB(CNY) and so forth.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">Asia Pacific Industry Group Co., Limited are our company who deal with our exporting business, and any other third company are not our company.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">Additionally, regarding to Iran buyers, we particularly issue the Kunlun bank for all of our Iran buyer, so that all of our Iran buyer can send their payment to us directly from their Iran local bank, it was convenience and safety for buyers.</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <br/></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q5: How to control your quantity and quality?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A. 1) A complete quality guarantee system: IQC→ FAS &amp; Self-checking for each process→ OQC;</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">2) IS09001: 2008 system, SGS, BV.COTECNA, SONCAP approved</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">3.) Third parties to inspection</span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;"><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Q6: How can we get a quote?</span></strong></span></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;line-height:24px;font-family:Tahoma;font-size:18px;">A: Buyer can get our quotation via Email (all of our email are <a href="mailto:sales@boppfilmsales.com">sales@boppfilmsales.com</a>), Tel, Fax, Mobile (cellphone) message, Skype,Wechats, or any other methods. Please offer us the specification of the product that you need, then we will quote our price to you Within 2 hours during the working time, and within 12 hours during non-working time, and Within 24 hours during the holidays.</span></p> <p><br/></p> <p><span><br/> </span></p> <p><span><br/> </span></p> <span style=''line-height:24px;font-family:Calibri, "font-size:24px;''> <p><br/></p> <p align="left" style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <br/></p> </span> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:20px;"><span style=''font-family:"''><img alt="" border="0" height="480" src="../images/no-photo.png" width="348"/><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> The spirit of Mount Huangshan pine</span><br/> <br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> To headwind Aoxue self-reliance spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Indomitable fighting spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Indomitable enterprising spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Congregation wood forest solidarity</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Guang Ying universally spirit of openness</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Wholehearted dedication</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:20px;"><span style=''font-family:"''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Taiwanensis spirit is a kind of national spirit, a spirit of the times.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> We should learn taiwanensis glorify taiwanensis spirit, let taiwanensis spirit passed on from generation to generation.</span><br/> <br/> <br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Huishang spirit</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:20px;"><span style=''font-family:"''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Patriotic An Min patriotism</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Indomitable enterprising spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> The spirit of the trend of the degree of potential competition</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Thrifty spirit of the benefits without costs</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Dedication of the justice system Lee</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> The cultural spirit of Confucianism as well</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> A public Bangzhong team spirit</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Dedication of loyal and dedicated</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:20px;"><span style=''font-family:"''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">The emblem of culture shaping the Huizhou merchants the character - Rushang, Confucian culture to guide business</span>.</span></span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (1, 100, 'Group products introduce', '../', '<p></p><p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><strong><span style="color:#009900;font-family:Verdana;font-size:18px;">O</span></strong><span style="color:#009900;font-family:Verdana;font-size:18px;">ur main products diversified followings:</span><br/> <strong><span style="color:#009900;font-family:Verdana;font-size:18px;">1. Flexible plastic packaging film industry</span><br/> </strong><span style="color:#009900;font-family:Verdana;font-size:18px;">1.) BOPP film including BOPP plain film (BOPP flower wrapping film, BOPP tape-grade film, BOPP clothes/bag-grade film, BOPP mini/smaller roll, BOPP Sheets) ,BOPP anti-static film, BOPP capacitor film;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">BOPP heat sealable film, BOPP tobacco film, BOPP straw film;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">BOPP matte film; BOPP pearlized film;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">BOPP thermal laminating film, BOPP tear tape;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">BOPP anti-fog film, BOPP micro/ macro perforated film;</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">Metallized BOPP film (VMBOPP), silver and golden metallized BOPP, laser</span><span style="color:#009900;font-family:Verdana;font-size:18px;">holographic BOPP film,</span><span style="color:#009900;font-family:Verdana;font-size:18px;">and so on.</span></span></span> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">2.) BOPET film including BOPP packing film , BOPET lamination film , BOPET insulation film, BOPET capacitor film, 4.5Microns BOPET thermal transfer film, BOPET sheets, sliver metallized BOPET film and so on.</span></span></span></p> <p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style="color:#009900;font-family:Verdana;font-size:18px;">3.) CPP film including CPP printing film, CPP laminating film, CPP bag film, retort CPP film , metallized cpp film and so on.</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">4.) BOPA film including BOPA printing and laminating film</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">5.) BOPS film including BOPS window envelop film, BOPS shrinkage film and BOPS sheets.</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">6.) PE film including PE stretch film for pallets packaging of machine /hand use , PE cling film for food wrapping, PE bags,PE zipper and so on.</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">7.) PVC cling film and POF shrink cling film. </span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">8.) Tear tape, tear clip, tape for dates/opening tape, thermal color transfer film.</span></span></span></p> <p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <br/></p> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''></span></span> <p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><br/> <strong><span style="color:#009900;font-family:Verdana;font-size:18px;">2. Coating film</span><br/> </strong><span style="color:#009900;font-family:Verdana;font-size:18px;">1.) BOPP adhesive tape clear and color ( jumbo rolls and slit smaller rolls); masking tapes jumbo rolls( jumbo rolls and slit smaller rolls), double sides jumbo rolls( jumbo rolls and slit smaller rolls), hot melt solvent tape jumbo rolls( jumbo rolls and slit smaller rolls), and so on.</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">2.) EVA coating film of BOPP/BOPET/BOPA (thermal lamination film)</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">3.) PVDC coating film of BOPP/BOPET/BOPA</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">4.) Acrylic coating film</span></span></span></p> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''></span></span> <p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><br/> <strong><span style="color:#009900;font-family:Verdana;font-size:18px;">3. Glue industry and chemical relative products industry</span><br/> </strong><span style="color:#009900;font-family:Verdana;font-size:18px;">1.) Adhesive glue and raw materials, including butyl acrylate, EVA glue, PVDC glue, and color printing pigment and liquid raw materials.</span></span></span></p> <p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><br/> <strong><span style="color:#009900;font-family:Verdana;font-size:18px;">4. Deep processing of the film series and plastic products industry</span><br/> </strong><span style="color:#009900;font-family:Verdana;font-size:18px;">1.) film slitting 2.)film color printing 3.) film coating 4.) film aluminized 5.) film bag 6.) film basic self-adhesive tear tape7.) plastic cards 8)plastic toys 9.) PP, CPP, PE, and other raw material particles 10.) mold, leather, rubber products.</span></span></span></p> <p align="left" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <br/></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:20px;''></span></p> <div style="text-align:left;color:#59595B;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-size:18px;"><span style=''font-family:"font-size:20px;''><span style="color:#009900;font-family:Verdana;font-size:18px;">5</span><span style="color:#009900;font-family:Verdana;font-size:18px;">.</span><span style="color:#009900;font-family:Verdana;font-size:18px;">Printing inkjet supplies Series: </span></span></span> </div> <p><span style=''color:#59595B;font-family:"font-size:20px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style=''line-height:20px;font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style="color:#009900;font-family:Verdana;font-size:18px;">Wax,resin Ribbon (jumbo rolls and small finished rolls), color Ribbon (jumbo rolls and small finished rolls), date tape</span><br/> <span style="color:#009900;font-family:Verdana;font-size:18px;">(jumbo rolls and small finished rolls)</span><span style="color:#009900;font-family:Verdana;font-size:18px;">, self adhesive labels (including roll and pages), the Mexican round, printers, etc. </span></span></span></span></span></p> <p><span style=''color:#59595B;font-family:"font-size:20px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style=''line-height:20px;font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style="color:#009900;font-family:Verdana;font-size:18px;"><span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:36px;''><span style=''color:#000000;font-family:"font-size:36px;font-weight:normal;''><span><span><span style=''line-height:20px;font-family:"font-size:20px;''><span style="color:#009900;font-family:Verdana;font-size:18px;">6. Wrap wire, tear clips and self adhesive tear tape:</span><span style="color:#009900;font-family:Verdana;font-size:18px;"><span style="color:#009900;font-family:Verdana;font-size:18px;">plastic tear clips, tear tape,tie lines and metal cable and so on.</span></span></span></span></span></span></span></span></span> </span></span></span></span></span></p> <p><span style=''color:#59595B;font-family:"font-size:20px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style=''line-height:20px;font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style="color:#009900;font-family:Verdana;font-size:18px;"><br/> </span></span></span></span></span></p> <p><span style=''color:#59595B;font-family:"font-size:20px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style=''line-height:20px;font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style="color:#009900;font-family:Verdana;font-size:18px;"><span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;font-weight:bold;''><span style="color:#009900;font-family:Verdana;font-size:18px;"><span style="color:#009900;font-family:Verdana;font-size:18px;">7</span></span></span></span></span></span></span></span></span><span style="color:#009900;font-family:Verdana;font-size:18px;">. Paper products and printing supplies series industry</span></p> <p><span style=''color:#59595B;font-family:"font-size:20px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style=''line-height:20px;font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style=''font-family:"font-size:20px;''><span style="color:#009900;font-family:Verdana;font-size:18px;"><span style=''font-family:"font-size:20px;''> <span style="color:#009900;font-family:Verdana;font-size:18px;">1.) office copy paper (reams and rolls) 2.) LWC paper (lower/light weight coated paper) and Coated paper 3.) printing supplies series of photo inkjet paper 4.) outdoor advertising supplies series, 5.) light box cloth series; 6.) Offset paper and News printing paper 7.) other products as well as flowers, gift wrapping paper, specialty paper.</span></span></span></span></span></span></span></p> <p><span style="color:#59595B;"><span style="line-height:20px;"><span style="color:#009900;font-size:18px;"><span style=''font-family:"font-size:20px;''><br/> </span><span style="color:#009900;font-size:18px;"><span>8</span></span><span style="font-family:Verdana;color:#009900;font-size:18px;">. Machinery equipment and machine parts industry</span><br/> <span style=''font-family:"font-size:24px;color:#009900;''><span style="color:#009900;font-family:Verdana;font-size:18px;">1.) Film and tape slitting machine series 2.) All kinds of glue products in the coating machine series 3.) Film printing machine series 4.) Film packing, composite, rewinding machine serie</span><span style="color:#009900;font-family:Verdana;font-size:18px;">s 5.) shrink machine, wrapping machine, sealing machine 6.) as well as the above types of machine parts.</span></span> </span></span></span></p> <span style="font-family:微软雅黑, sans-serif;"><span style="color:#333333;font-family:arial;font-size:13px;background-color:#FFFFFF;"><span><span><s